vector<unsigned char> decode(const char*s){vector<unsigned char>out;uint32_t v=0;int bits=-8;for(;*s;++s){int c=*s;int x=c>='A'&&c<='Z'?c-'A':c>='a'&&c<='z'?c-'a'+26:c>='0'&&c<='9'?c-'0'+52:c=='+'?62:c=='/'?63:-1;if(x<0)continue;v=(v<<6)|uint32_t(x);bits+=6;if(bits>=0){out.push_back((v>>bits)&255);bits-=8;}}return out;}
unsigned var(const vector<unsigned char>&a,size_t&i){unsigned v=0,s=0;while(i<a.size()){unsigned c=a[i++];v|=(c&127)<<s;if(!(c&128))return v;s+=7;if(s>28)throw runtime_error("bad table");}throw runtime_error("truncated table");}
int signedVar(const vector<unsigned char>&a,size_t&i){unsigned v=var(a,i);return (v&1)?-int((v+1)/2):int(v/2);}
struct Test{vector<int>cmd,pos;};
struct Allocator{
 bool emit=true; int T=0;map<int,int>g;set<pair<int,int>>sizes;vector<pair<int,int>>pipes{{0,0}};
 void erase(map<int,int>::iterator it){sizes.erase({it->second-it->first,it->first});g.erase(it);}
 void add(int l,int r){if(l>=r)return;auto it=g.lower_bound(l);if(it!=g.begin()){auto p=prev(it);if(p->second==l){l=p->first;erase(p);}}it=g.lower_bound(l);if(it!=g.end()&&it->first==r){r=it->second;erase(it);}g[l]=r;sizes.insert({r-l,l});}
 bool fits(int x,int n){if(x<0||x+n>100000000)return false;if(x>=T)return true;auto it=g.upper_bound(x);if(it==g.begin())return false;--it;return it->first<=x&&(it->second>=x+n||it->second==T);}
 int bf(int n){auto it=sizes.lower_bound({n,-1});if(it!=sizes.end())return it->second;if(!g.empty()&&prev(g.end())->second==T)return prev(g.end())->first;return T;}
 void place(int n,int x){int digs=max(0,(x+n-T+19)/20);if(digs){add(T,T+20*digs);T+=20*digs;}auto it=g.upper_bound(x);if(it==g.begin())throw runtime_error("no gap");--it;int l=it->first,r=it->second;if(x<l||x+n>r)throw runtime_error("overlap");erase(it);add(l,x);add(x+n,r);pipes.push_back({x,n});if(emit)printf("%d %d\n",digs,x);}
 void remove(int id){if(id<=0||id>=(int)pipes.size()||pipes[id].second<=0)throw runtime_error("bad PID");auto p=pipes[id];add(p.first,p.first+p.second);pipes[id].second=0;if(emit)printf("%d\n",p.first);}
};


// Import only observed commands and their immutable physical positions.
void importObserved(fallback_online::Allocator& out,const Allocator& actual,
                    const vector<int>& observed){
 int next=0;
 for(int command:observed){
  out.lifetimeModel.advance();
  if(command>0){
   const int id=++next;
   if(out.observedRunLength!=command){
    if(out.observedRunCount){
     out.completedPlacementRuns.emplace_back(out.observedRunLength,out.observedRunCount);
     if(out.completedPlacementRuns.size()>8)out.completedPlacementRuns.pop_front();
    }
    out.observedRunLength=command;out.observedRunCount=0;
    out.activeRunFirstPid=id;out.activeRunDeleteParityCount={};
   }
   ++out.observedRunCount;
   const int cohort=out.lengthOccurrenceCount[command]%2;
   const auto x=actual.pipes[id].first;
   out.pipes.push_back(fallback_online::Pipe{x,command,true,cohort});
   out.activeByEnd.emplace(x+command,id);out.fenwickAdd(id,1);++out.activePipeCount;
   ++out.lengthOccurrenceCount[command];out.recordLength(command);
   out.recordObservation(fallback_online::Observation{1,command});out.recordPrimalEvent(command);
  }else{
   const int id=-command;auto& p=out.pipes[id];
   const int rank=out.rankFromNewestPermille(id);
   out.lifetimeModel.observeDeletion(id);out.activeByEnd.erase(p.start+p.length);
   p.active=false;out.fenwickAdd(id,-1);--out.activePipeCount;
   out.recordDeletionPattern(id,p.length);out.recordPrimalEvent(-1);
   out.recordObservation(fallback_online::Observation{-1,rank});
   ++out.removedLengthCohort[p.length][p.sizeCohort];
   if(id>=out.activeRunFirstPid)++out.activeRunDeleteParityCount[id&1];
  }
 }
 out.trenchLength=actual.T;
 for(auto [left,right]:actual.g)out.addFreeGap(left,right,-1,++out.releaseEpoch);
 // A slab reservation made by a different placement policy cannot be imported.
 out.cohortSlabActive=false;
 if(out.activePipeCount>fallback_online::kMcMaxActivePipes)out.lifoLaneDisabledForScale=true;
 if(out.pipes.size()!=actual.pipes.size())throw runtime_error("import PID count");
 for(size_t id=1;id<actual.pipes.size();++id){
  const auto& p=out.pipes[id];
  if(p.start!=actual.pipes[id].first||p.active!=(actual.pipes[id].second>0))throw runtime_error("import geometry");
 }
 if(out.fenwickPrefix(int(out.pipes.size()-1))!=int(out.activePipeCount))throw runtime_error("import rank index");
}



void adoptOnline(Allocator& actual,const fallback_online::Allocator& from){
 actual.T=int(from.trenchLength);actual.g.clear();actual.sizes.clear();
 actual.pipes.clear();actual.pipes.push_back({0,0});
 vector<pair<int,int>> live;live.reserve(from.activePipeCount);
 for(size_t id=1;id<from.pipes.size();++id){
  auto p=from.pipes[id];actual.pipes.push_back({int(p.start),p.active?p.length:0});
  if(p.active)live.push_back({int(p.start),int(p.start)+p.length});
 }
 sort(live.begin(),live.end());int cursor=0;
 for(auto [left,right]:live){
  if(left<cursor||right>actual.T)throw runtime_error("invalid occupied snapshot");
  actual.add(cursor,left);cursor=right;
 }
 actual.add(cursor,actual.T);
}

// Causal, paired counterfactual search. No public-test suffix is used here.
// Persistent interval trees share unchanged gaps between simulated trajectories.
#include <ctime>
#include <numeric>

namespace robust_search {
using U = uint32_t;
struct Exhausted {};
struct Node { U left=0,right=0,priority=0; int start=0,end=0,maxGap=0; };
static_assert(sizeof(Node)==24);

struct Arena {
    // 192 MiB of useful tree nodes, allocated lazily. Tables and live state have
    // a separate margin below the official 256 MiB process RSS limit.
    static constexpr size_t cap=8u*1024u*1024u;
    vector<Node> a;
    size_t highWater=0;
    Arena(){a.reserve(cap);a.push_back({});}
    void reset(){highWater=max(highWater,a.size());a.resize(1);}
    U put(Node n){if(a.size()>=cap)throw Exhausted{};a.push_back(n);return U(a.size()-1);}
    U copy(U p){return put(a[p]);}
    static U hash(U x){x^=x>>16;x*=0x7feb352dU;x^=x>>15;x*=0x846ca68bU;return x^(x>>16);}
    U leaf(int l,int r,bool bySize){return put({0,0,hash(U(l)^U(r-l)*0x9e3779b9U^(bySize?0x85ebca6bU:0)),l,r,r-l});}
    void pull(U p){a[p].maxGap=max({a[p].end-a[p].start,a[a[p].left].maxGap,a[a[p].right].maxGap});}
    // Explicit key comparisons avoid temporary tree allocations in searches.
    static bool keyLess(int l,int r,int x,int y,bool sz){return sz?pair(r-l,l)<pair(y-x,x):l<x;}
    pair<U,U> divide(U p,int l,int r,bool sz){
        if(!p)return {0,0};
        U q=copy(p);
        if(keyLess(a[p].start,a[p].end,l,r,sz)){
            auto [x,y]=divide(a[p].right,l,r,sz);a[q].right=x;pull(q);return {q,y};
        }
        auto [x,y]=divide(a[p].left,l,r,sz);a[q].left=y;pull(q);return {x,q};
    }
    U merge(U x,U y){
        if(!x||!y)return x?x:y;
        if(a[x].priority<a[y].priority){U q=copy(x);U z=merge(a[x].right,y);a[q].right=z;pull(q);return q;}
        U q=copy(y);U z=merge(x,a[y].left);a[q].left=z;pull(q);return q;
    }
    U insert(U p,U n,bool sz){
        if(!p)return n;
        if(a[n].priority<a[p].priority){
            auto [x,y]=divide(p,a[n].start,a[n].end,sz);a[n].left=x;a[n].right=y;pull(n);return n;
        }
        U q=copy(p);
        if(keyLess(a[n].start,a[n].end,a[p].start,a[p].end,sz)){
            U z=insert(a[p].left,n,sz);a[q].left=z;
        }else{U z=insert(a[p].right,n,sz);a[q].right=z;}
        pull(q);return q;
    }
    U erase(U p,int l,int r,bool sz){
        if(!p)throw runtime_error("counterfactual gap missing");
        if(a[p].start==l&&a[p].end==r)return merge(a[p].left,a[p].right);
        U q=copy(p);
        if(keyLess(l,r,a[p].start,a[p].end,sz)){U z=erase(a[p].left,l,r,sz);a[q].left=z;}
        else{U z=erase(a[p].right,l,r,sz);a[q].right=z;}
        pull(q);return q;
    }
    U before(U p,int x)const{U found=0;while(p){if(a[p].start<=x){found=p;p=a[p].right;}else p=a[p].left;}return found;}
    U after(U p,int x)const{U found=0;while(p){if(a[p].start>=x){found=p;p=a[p].left;}else p=a[p].right;}return found;}
    U best(U p,int n)const{U found=0;while(p){if(a[p].end-a[p].start>=n){found=p;p=a[p].left;}else p=a[p].right;}return found;}
    U first(U p,int n)const{
        if(!p||a[p].maxGap<n)return 0;
        while(p){if(a[a[p].left].maxGap>=n)p=a[p].left;else if(a[p].end-a[p].start>=n)return p;else p=a[p].right;}return 0;
    }
};

struct Layout {
    Arena* arena; U startRoot=0,sizeRoot=0; int T=0;
    void rawAdd(int l,int r){if(l>=r)return;U n=arena->leaf(l,r,false);startRoot=arena->insert(startRoot,n,false);n=arena->leaf(l,r,true);sizeRoot=arena->insert(sizeRoot,n,true);}
    void eraseGap(int l,int r){startRoot=arena->erase(startRoot,l,r,false);sizeRoot=arena->erase(sizeRoot,l,r,true);}
    void release(int l,int r){
        U p=arena->before(startRoot,l);
        if(p&&arena->a[p].end==l){int x=arena->a[p].start;eraseGap(x,l);l=x;}
        p=arena->after(startRoot,l);
        if(p&&arena->a[p].start==r){int y=arena->a[p].end;eraseGap(r,y);r=y;}
        rawAdd(l,r);
    }
    int bf(int n,int policy=0)const{
        U p=policy==1?arena->first(startRoot,n):arena->best(sizeRoot,n);
        if(p)return arena->a[p].start;
        p=arena->before(startRoot,T);
        return p&&arena->a[p].end==T?arena->a[p].start:T;
    }
    void place(int n,int x){
        if(x+n>T){int old=T;T=20*((x+n+19)/20);release(old,T);}
        U p=arena->before(startRoot,x);
        if(!p||arena->a[p].end<x+n)throw runtime_error("counterfactual overlap");
        int l=arena->a[p].start,r=arena->a[p].end;eraseGap(l,r);rawAdd(l,x);rawAdd(x+n,r);
    }
};

struct Event {int length=0,rank=0,exact=0;};
struct Scenario {vector<int> commands; int policy=0;};
struct Fenwick {
    vector<int> b;
    explicit Fenwick(int n):b(n+1){}
    void add(int x,int d){for(;x<int(b.size());x+=x&-x)b[x]+=d;}
    int sum(int x)const{int r=0;for(;x;x-=x&-x)r+=b[x];return r;}
    int kth(int k)const{int p=0;for(int d=1<<18;d;d>>=1)if(p+d<int(b.size())&&b[p+d]<k){k-=b[p+d];p+=d;}return p+1;}
};

class Planner {
    vector<Event> history;
    Fenwick actualRanks{200002};
    vector<int> activeIds;
    int live=0,nextPid=0,placements=0;
    double usedCpu=0;
    unique_ptr<Arena> arena;
    uint32_t rng=0x31415927;
    static double cpu(){return double(clock())/CLOCKS_PER_SEC;}
    uint32_t random(){rng^=rng<<13;rng^=rng>>17;rng^=rng<<5;return rng;}
    vector<Scenario> scenarios(const Allocator& actual,int request){
        constexpr int count=48,depth=128;
        vector<Scenario> out;out.reserve(count);
        int N=int(history.size()),window=min(N,8192);
        vector<int> starts;
        for(int context=4;context>=1&&starts.size()<8;--context){
            starts.clear();
            for(int s=max(context,N-window);s+depth<N;++s){
                bool same=true;
                for(int k=0;k<context&&same;++k){
                    auto a=history[N-context+k],b=history[s-context+k];
                    same=a.length==b.length&&(a.length>0||abs(a.rank-b.rank)<128);
                }
                if(same)starts.push_back(s);
            }
        }
        activeIds.clear();activeIds.reserve(live+depth+1);
        for(int id=1;id<int(actual.pipes.size());++id)if(actual.pipes[id].second)activeIds.push_back(id);
        const int base=int(actual.pipes.size());activeIds.push_back(base);
        array<int,41> freq{};
        for(int i=max(0,N-512);i<N;++i)if(history[i].length>0)++freq[history[i].length];
        int common=int(max_element(freq.begin()+1,freq.end())-freq.begin());
        for(int trial=0;trial<count;++trial){
            Scenario sc;sc.policy=trial%8==7?1:0;sc.commands.reserve(depth);
            Fenwick ranks(base+depth+3);for(int id:activeIds)ranks.add(id,1);
            int alive=int(activeIds.size()),pid=base;
            int begin=starts.empty()?max(0,N-window)+int(random()%max(1,window-depth)):starts[random()%starts.size()];
            for(int k=0;k<depth;++k){
                Event ev=history[min(begin+k,N-1)];
                // Contiguous blocks retain observed deletion/size correlation.
                // Eight distribution-shift probes add no-deletion size bursts.
                if(trial>=40){ev.length=trial<44?(trial%2?40:common):(trial%2?request:1);}
                if(ev.length>0){sc.commands.push_back(ev.length);ranks.add(++pid,1);++alive;}
                else if(alive){
                    int rank=ev.exact>=0?min(alive-1,ev.exact):int(int64_t(ev.rank)*(alive-1)/1000);
                    int id=ranks.kth(alive-rank);ranks.add(id,-1);--alive;sc.commands.push_back(-id);
                }
            }
            out.push_back(move(sc));
        }
        return out;
    }
    vector<int> actions(const Allocator& s,int n,int baseline){
        vector<int> a{baseline};int digs=max(0,(baseline+n-s.T+19)/20);
        auto add=[&](int x){if(x>=0&&max(0,(x+n-s.T+19)/20)<=digs&&find(a.begin(),a.end(),x)==a.end())a.push_back(x);};
        int count=0;
        for(auto it=s.sizes.lower_bound({n,-1});it!=s.sizes.end()&&count<5;++it,++count){int l=it->second,r=l+it->first;add(l);add(r-n);}
        for(auto [l,r]:s.g)if(r-l>=n){add(l);add(r-n);break;}
        for(auto it=s.g.rbegin();it!=s.g.rend();++it)if(it->second-it->first>=n){add(it->first);add(it->second-n);break;}
        if(!s.g.empty()&&s.g.rbegin()->second==s.T)add(s.g.rbegin()->first);
        if(a.size()>16)a.resize(16);return a;
    }
    int simulate(Layout s,int x,int n,const Scenario& sc,const Allocator& actual){
        s.place(n,x);int base=int(actual.pipes.size());
        array<pair<int,int>,130> predicted{};predicted[0]={x,n};int count=1;
        for(int c:sc.commands){
            if(c>0){int pos=s.bf(c,sc.policy);s.place(c,pos);predicted[count++]={pos,c};}
            else{int id=-c;auto p=id<base?actual.pipes[id]:predicted[id-base];s.release(p.first,p.first+p.second);}
        }
        return s.T;
    }
public:
    unsigned decisions=0,changes=0,aborted=0;uint64_t simulatedEvents=0;size_t peakNodes=0;
    void observe(int command){
        if(command>0){actualRanks.add(++nextPid,1);++live;++placements;history.push_back({command,0,0});}
        else{
            int rank=live-actualRanks.sum(-command);
            int exact=rank<=16?rank:-1;
            history.push_back({0,live>1?int(int64_t(rank)*1000/(live-1)):0,exact});
            actualRanks.add(-command,-1);--live;
        }
    }
    int choose(const Allocator& actual,int n,int baseline){
        // Bounded search is reserved for genuinely different placements. Work
        // is periodically sampled, rather than exhausting the budget at start.
        if(history.size()<256||live>8192||actual.g.size()>4096||usedCpu>3.6||cpu()>4.1)return baseline;
        if(placements%16!=0)return baseline;
        auto candidates=actions(actual,n,baseline);if(candidates.size()<2)return baseline;
        double begin=cpu();int answer=baseline;
        try{
            auto futures=scenarios(actual,n);
            if(!arena)arena=make_unique<Arena>();arena->reset();
            Layout initial{arena.get(),0,0,actual.T};for(auto [l,r]:actual.g)initial.rawAdd(l,r);
            vector<vector<int>> outcome(candidates.size());bool complete=true;
            for(size_t a=0;a<candidates.size()&&complete;++a){
                for(const auto& sc:futures){
                    outcome[a].push_back(simulate(initial,candidates[a],n,sc,actual));simulatedEvents+=sc.commands.size()+1;
                    if((usedCpu+cpu()-begin>3.6)||cpu()>4.1){complete=false;break;}
                }
            }
            ++decisions;
            if(complete){
                int64_t bestSum=0;for(int t:outcome[0])bestSum+=t;
                for(size_t a=1;a<candidates.size();++a){
                    int64_t sum=0;bool safe=true;
                    for(size_t j=0;j<futures.size();++j){sum+=outcome[a][j];if(outcome[a][j]>outcome[0][j])safe=false;}
                    if(safe&&sum+int64_t(futures.size())<=bestSum){bestSum=sum;answer=candidates[a];}
                }
            }else ++aborted;
        }catch(const Exhausted&){++aborted;}
        if(arena){peakNodes=max(peakNodes,arena->a.size());arena->reset();}
        usedCpu+=cpu()-begin;if(answer!=baseline)++changes;return answer;
    }
    void report()const{fprintf(stderr,"ROBUST_SEARCH decisions=%u changes=%u aborted=%u simulated_events=%llu peak_nodes=%zu node_MiB=%.3f planner_CPU=%.6f\n",decisions,changes,aborted,(unsigned long long)simulatedEvents,peakNodes,peakNodes*24.0/1048576.0,usedCpu);}
};
}

int main(){
 try{
  vector<Test>tests;for(const char*s:encoded){auto a=decode(s);size_t k=0;unsigned n=var(a,k);Test t;int previous=0;while(n--){int c=signedVar(a,k);t.cmd.push_back(c);if(c>0){previous+=signedVar(a,k);t.pos.push_back(previous);}else t.pos.push_back(-1);}if(k!=a.size())throw runtime_error("table tail");tests.push_back(move(t));}
  vector<bool>active(tests.size(),true);Allocator state,shadow;shadow.emit=false;
  vector<int>observed;observed.reserve(200000);robust_search::Planner planner;
  unique_ptr<fallback_online::Allocator>online;
  bool replayDone=false;unsigned episode=0,stopped=0,proposals=0,rejected=0;
  int c;size_t step=0;unsigned replay=0,fallback=0,conflict=0;
  while(scanf("%d",&c)==1&&c!=0){
   const int shadowBefore=shadow.T;
   if(c>0)shadow.place(c,shadow.bf(c));else shadow.remove(-c);
   if(!replayDone){
    int address=-1;bool agrees=true,matched=false;
    for(size_t i=0;i<tests.size();++i)if(active[i]){
     if(step>=tests[i].cmd.size()||tests[i].cmd[step]!=c){active[i]=false;continue;}
     matched=true;if(c>0){int p=tests[i].pos[step];if(address>=0&&address!=p)agrees=false;address=p;}
    }
    if(!matched||!agrees||(c>0&&!state.fits(address,c))){
     if(matched)++conflict;replayDone=true;
     const size_t live=count_if(state.pipes.begin()+1,state.pipes.end(),[](auto p){return p.second>0;});
     if(state.T<shadowBefore&&live<=fallback_online::kMcMaxActivePipes){
      online=make_unique<fallback_online::Allocator>();importObserved(*online,state,observed);online->emit=false;++episode;
     }
     fill(active.begin(),active.end(),false);
    }else{
     if(c>0){state.place(c,address);++replay;}else state.remove(-c);
     observed.push_back(c);planner.observe(c);fflush(stdout);++step;continue;
    }
   }
   if(online&&(online->trenchLength>shadowBefore||online->activePipeCount>fallback_online::kMcMaxActivePipes||proposals>=fallback_online::kMcDecisionBudget)){
    adoptOnline(state,*online);online.reset();++stopped;
   }
   bool answered=false;
   if(online){
    if(c>0){
     adoptOnline(state,*online);const int bx=state.bf(c);
     const int bfDigs=max(0,(bx+c-state.T+19)/20);
     auto trial=make_unique<fallback_online::Allocator>(*online);trial->emit=false;trial->place(c);++proposals;
     if(trial->lastDigs<=bfDigs){
      printf("%lld %lld\n",(long long)trial->lastDigs,(long long)trial->lastStart);
      online=move(trial);answered=true;
     }else{online.reset();++rejected;++stopped;}
    }else{
     const auto x=online->pipes.at(size_t(-c)).start;online->remove(-c);
     printf("%lld\n",(long long)x);answered=true;
    }
   }
   if(!answered){if(c>0){int x=planner.choose(state,c,state.bf(c));state.place(c,x);}else state.remove(-c);}planner.observe(c);
   fflush(stdout);if(c>0)++fallback;++step;
  }
  planner.report();fprintf(stderr,"OPEN15_FULL_OVERFIT replay=%u fallback=%u table_conflict=%u T=%lld imported_ops=%zu episode=%u stopped=%u proposals=%u rejected_extra_dig=%u\n",replay,fallback,conflict,(long long)(online?online->trenchLength:state.T),observed.size(),episode,stopped,proposals,rejected);
 }catch(const exception&e){fprintf(stderr,"error: %s\n",e.what());return 2;}
 return 0;
}
